3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Assigns the {@code membershipPoints} score and the derived numeric {@code membershipLevel} at
11	 * creation time. Points start at {@code 0} and accrue: {@code 2} when the owner has an email,
12	 * {@code 1} when {@code namesakeCount} is {@code 0}, {@code 2} for a household of {@code 3} or more
13	 * (from {@code householdSize}), and {@code 3} for tenure over {@code 365} days (days between the
14	 * owner's {@code registrationDate} and the current server date). Points map to a level as
15	 * {@code 1} (0-1 points), {@code 2} (2-3), {@code 3} (4-5) and {@code 4} (6 or more). Runs after
16	 * {@link CountNamesakes} and {@link CountHousehold} so both counts are already set.
17	 */
18	public class AssignMembershipLevel {
19	
20	    /** Tenure, in days, above which the owner qualifies for the tenure points. */
21	    private static final long TENURE_THRESHOLD_DAYS = 365;
22	
23	    /** Household size at or above which the household points are awarded. */
24	    private static final int HOUSEHOLD_THRESHOLD = 3;
25	
26	    public void service(@Val Owner owner) {
27	        int points = 0;
28	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
29	            points += 2;
30	        }
31	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
32	            points += 1;
33	        }
34	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_THRESHOLD) {
35	            points += 2;
36	        }
37	        if (tenureDays(owner) > TENURE_THRESHOLD_DAYS) {
38	            points += 3;
39	        }
40	        owner.setMembershipPoints(points);
41	        owner.setMembershipLevel(levelForPoints(points));
42	    }
43	
44	    private static int levelForPoints(int points) {
45	        if (points <= 1) {
46	            return 1;
47	        }
48	        if (points <= 3) {
49	            return 2;
50	        }
51	        if (points <= 5) {
52	            return 3;
53	        }
54	        return 4;
55	    }
56	
57	    private static long tenureDays(Owner owner) {
58	        LocalDate registrationDate = owner.getRegistrationDate();
59	        if (registrationDate == null) {
60	            return 0;
61	        }
62	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
63	    }
64	}
